      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "The effectiveness of organisational-level workplace mental health interventions on mental health and wellbeing in construction workers: A systematic review and recommended research agenda.",
      "reason": "The title explicitly includes the phrase 'A systematic review', identifying the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "The effectiveness of organisational-level workplace mental health interventions on mental health and wellbeing in construction workers: A systematic review and recommended research agenda.",
      "reason": "The title specifies the population ('construction workers') and the intervention/exposure focus ('organisational-level workplace mental health interventions'), providing key information about the review question."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The title does not include supplementary information such as analysis method, included study designs, update status, or living-review status."
    }
  ],
  "confidence": "90"
