{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_21",
      "quote": "This systematic review aimed to assess recent scientific evidence on the effectiveness of organisational-level mental health interventions on non-clinical mental health outcomes and mental wellbeing in the construction industry in general and in SMEs in particular. This review identified a low number of studies on this topic with only one study of moderate methodological quality... The evidence found in the four studies was not sufficient to develop specific recommendations for the design of organisational-level mental health promotion programmes in the construction industry and more specifically for SMEs.",
      "reason": "The manuscript describes the current state of knowledge (few studies, low-quality evidence, heterogeneous interventions) and highlights important uncertainties (insufficient evidence to make recommendations), fulfilling the requirement to describe the current state and uncertainties."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_22",
      "quote": "Develop and evaluate mental health interventions specific to the working situation in the construction sector. Only one study included in this systematic review addressed the specific psychosocial working conditions of construction workers... Tailoring the intervention more specifically to the workplace may be particularly relevant for the construction industry... There is a rich opportunity for scientific effectiveness and process evaluation of existing and future workplace mental health programmes to determine whether they actually result in mental health improvements, which programme elements are the most effective and which approaches can be best implemented into the construction work environment.",
      "reason": "The authors explain the importance and need for conducting the review by outlining gaps (e.g. interventions not tailored to construction, lack of robust evaluation) and articulating the need for future research and evaluation, justifying the review's necessity."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was found in the provided text that discusses existing similar systematic reviews or explains the need for the current review relative to prior reviews; therefore the conditional requirement is not addressed in the supplied evidence."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": "text_22",
      "quote": "Develop a programme theoretical framework. An explicit programme theory is necessary with specification of the expected short-term and long-term outcomes at different levels of the organisation, intermediary outcomes, and mechanisms of change to guide the intervention and evaluation and to avoid chance and error strategies. None of the studies included in our systematic review, spelled out such a model;",
      "reason": "Although the authors recommend describing mechanisms and programme theory for future work, they report that the included studies did not spell out mechanisms of action; the review itself does not describe a proposed mechanism of action for the interventions, so this conditional item is not fulfilled."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": "text_22",
      "quote": "Develop a programme theoretical framework. An explicit programme theory is necessary... None of the studies included in our systematic review, spelled out such a model; only one study took multi-level variations into account by performing multi-level analyses [73].",
      "reason": "The authors discuss the value of a logic model and note that none of the included studies provided such a model; the review does not present a logic model itself, so this conditional reporting element is not met in the provided evidence."
    }
  ],
  "confidence": 80
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "The specific review questions are: (1) Are organisational-level mental health programmes effective in reducing stress, burnout, non-clinical depressive and anxiety symptoms, and in enhancing mental wellbeing in construction workers? (2) Are organisational-level mental health programmes effective in reducing stress, burnout, non-clinical depressive and anxiety symptoms and in enhancing mental wellbeing in SME construction workers?",
      "reason": "The manuscript explicitly states the specific review questions addressing the objectives of the review, phrased as clear questions about the effectiveness of organisational-level mental health programmes in construction workers and in SME construction workers."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "The specific review questions are: (1) Are organisational-level mental health programmes effective in reducing stress, burnout, non-clinical depressive and anxiety symptoms, and in enhancing mental wellbeing in construction workers? (2) Are organisational-level mental health programmes effective in reducing stress, burnout, non-clinical depressive and anxiety symptoms and in enhancing mental wellbeing in SME construction workers?",
      "reason": "The review questions specify the population (construction workers, SMEs), the intervention type (organisational-level mental health programmes) and the outcomes of interest (stress, burnout, non-clinical depressive and anxiety symptoms, mental wellbeing) but do not present these planned comparisons in an explicit PICO (or similar labeled) format nor explicitly state comparators or detailed planned comparison structure; therefore the requirement for a PICO-formatted statement is only partially met."
    }
  ],
  "confidence": 80
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "Studies were included if they reported organisational-level mental health promotion interventions targeted at workers and/or managers within construction companies. In a staged approach only studies with a control group and with a before- and at least one after measurement post intervention were deemed eligible in the first round of selection as they provide the most robust evidence. These included randomised controlled trials (RCTs), a study design with participants randomly assigned to an intervention group and a control group; cluster randomised controlled trials (cRCT), with groups of participants (e.g., organisations) being randomised to an intervention and a control group, and non-randomised controlled trials. In a second stage, uncontrolled before- and after- designs and uncontrolled quasi-experimental designs were included in the reviews. Complete inclusion and exclusion criteria can be found in Table 1. Primary outcomes included quantitative measurements of aspects of mental health and wellbeing, secondary outcomes included organisational outcomes such as absenteeism, especially if linked to health issues, and changes to the psychosocial work environment.",
      "reason": "The manuscript specifies population (workers/managers in construction), eligible study designs (RCTs, cRCTs, non-randomised controlled trials, uncontrolled before-and-after, quasi-experimental), staged inclusion criteria, and primary/secondary outcomes."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "The search was performed using five databases on May 28, 2020, and updated on May 16, 2022: Academic Search Complete, PsycINFO, PubMed, Scopus and Web of Science and included studies published in English between January 2010 and May 2022 to reflect intervention efforts in the modern construction workplace. Unpublished 'grey literature' was not included.",
      "reason": "The review states date range (Jan 2010–May 2022), language restriction (English), databases searched and excludes grey literature / unpublished reports and specifies publication in peer-reviewed journals elsewhere."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PARTIAL",
      "chunk_id": "text_18",
      "quote": "Primary reasons for exclusion at full-text review were ineligible outcomes (n = 14) and ineligible study design (n = 10).",
      "reason": "The review explicitly reports exclusions for ineligible outcomes (i.e., outcomes not meeting criteria), but it does not report or distinguish exclusions due to outcome results not being reported (e.g., measured but not reported)."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "In a staged approach only studies with a control group and with a before- and at least one after measurement post intervention were deemed eligible in the first round of selection ... In a second stage, uncontrolled before- and after- designs and uncontrolled quasi-experimental designs were included in the reviews.",
      "reason": "The review describes grouping studies by design/stage (controlled designs first, then uncontrolled designs) but does not clearly specify the groups used in each synthesis nor explicitly link those groups to predefined comparisons in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "included studies published in English between January 2010 and May 2022 to reflect intervention efforts in the modern construction workplace. The search strategy aimed at identifying published studies ... Unpublished 'grey literature' was not included.",
      "reason": "The manuscript provides rationales for notable restrictions (timeframe to reflect modern workplace interventions; exclusion of grey literature; staged inclusion of study designs because controlled studies provide more robust evidence)."
    }
  ],
  "confidence": "85"
}

