{
  "item_id": "PRISMA_2020_8",
  "elements": [
    {
      "element_id": "prisma_2020_8_e1",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "To ensure adequate understanding and consistency in application of the inclusion and exclusion criteria, a sample of 20 records were selected at random and their titles and abstracts were reviewed and rated as 'eligible for inclusion' or 'not eligible for inclusion' independently by five authors (CL, CO'B, JCS, BG, BA)... Subsequently, two reviewers (CL, CO'B) completed a blinded title and abstract review of a random sample of 25% of records for inclusion... The remaining 75% of records were then screened at the title and abstract level by one reviewer (CL or CO'B). Blind screening of full-text articles was completed by two authors (CL and BG), who agreed on final inclusion and exclusion decisions.",
      "reason": "The text specifies how many reviewers participated at each screening stage: five for the 20-record sample, two for a 25% blinded title/abstract sample, one for the remaining 75% title/abstract screening, and two for blinded full-text screening."
    },
    {
      "element_id": "prisma_2020_8_e2",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "a sample of 20 records ... were reviewed and rated ... independently by five authors (CL, CO'B, JCS, BG, BA) with the Rayyan blinding feature enabled. Subsequently, two reviewers (CL, CO'B) completed a blinded title and abstract review of a random sample of 25% of records for inclusion... Blind screening of full-text articles was completed by two authors (CL and BG)...",
      "reason": "The text explicitly states reviewers worked independently/blinded for the 20-record sample, the 25% title/abstract sample, and that full-text screening was performed blinded by two authors."
    },
    {
      "element_id": "prisma_2020_8_e3",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "The five authors then met to discuss their inclusion decisions and any discrepancies were discussed until unanimous agreement was reached... Agreement between the reviewers was 98.3% with the discrepancies resolved through discussion and did not require the input of a third reviewer.",
      "reason": "The text describes the process used to resolve disagreements: group discussion until unanimous agreement for the five-author sample, and discussion between reviewers to resolve discrepancies for the 25% sample (no third reviewer required)."
    },
    {
      "element_id": "prisma_2020_8_e4",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "Where data were missing, incomplete or unclear, requests for additional information were sent to the corresponding study authors by email.",
      "reason": "The text reports that authors were contacted by email to obtain additional information when data were missing or unclear, which describes processes to obtain or confirm information from study investigators."
    },
    {
      "element_id": "prisma_2020_8_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_12",
      "quote": "The search ... included studies published in English between January 2010 and May 2022...",
      "reason": "The review included only studies published in English, so translation methods for abstracts or full articles for eligibility assessment do not apply."
    },
    {
      "element_id": "prisma_2020_8_e6",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "Results were exported into Rayyan QCRI, a software application to facilitate study selection in systematic reviews [70]. Duplicates were eliminated with the use of the Rayyan duplicate detection feature and verified by one reviewer (CL)... with the Rayyan blinding feature enabled.",
      "reason": "The authors report use of Rayyan QCRI and its duplicate-detection and blinding features, indicating integration of automation tools into the selection process."
    },
    {
      "element_id": "prisma_2020_8_e7",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_14",
      "quote": "Results were exported into Rayyan QCRI, a software application to facilitate study selection in systematic reviews [70]. Duplicates were eliminated with the use of the Rayyan duplicate detection feature and verified by one reviewer (CL).",
      "reason": "No externally derived classifiers are described or identified in the text; only use of Rayyan for duplicate detection and blinding is reported, so the item on externally derived classifiers does not apply."
    },
    {
      "element_id": "prisma_2020_8_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of internally derived classifiers, their training, or validation is reported; therefore this item does not apply."
    },
    {
